/*
 * Algorithm tracer: steps through a recorded run of an algorithm.
 *
 * Markup (generated by tools/trace/, see its README):
 *   <div class="pb-trace" data-pb-trace>
 *     <script type="application/json" class="pb-trace-data">{ title, code: [lines], layout: [components], frames: [...] }</script>
 *     <ol class="pb-trace-steps"> one <li> per frame </ol>     ← what readers see without JavaScript
 *   </div>
 *
 * Components (layout[i].type) and their per-frame state (frames[k].state[id]):
 *   array  { values?, marks: {index: cls}, ptrs: {name: index|null}, win: [l, r]|null }
 *   grid   { values?: [[...]], marks: {"r,c": cls} }
 *   list   { next: [index|null per node], ptrs: {name: index|null}, marks: {index: cls} }
 *   stack  { items: [...bottom→top], marks: {index: cls} }
 *   map    { entries: [[key, value]...], marks: {key: cls} }
 *   vars   { items: [[name, value]...] }
 *   queue  { items: [...front→back], marks: {index: cls} }
 *   graph  { marks: {id: cls}, edges: {"u-v": cls}, labels: {id: text}, values: {id: text}, hide: [id], ptrs: {name: id} }
 *          (trees, heaps and tries use graph too; layout carries node x/y, edges [u, v, weight?] and `directed`)
 * Arrays can render as bars (layout `bars: <rem per unit>`) with state `water: {index: units}`.
 * Any component with `inline: true` sits beside its neighbours instead of taking a full row.
 * Mark classes: hl ok bad swap dim win done best.
 */
(function () {
  "use strict";

  var PLAY_MS = 1300;

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = text;
    return e;
  }
  function svg(tag, attrs) {
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    Object.keys(attrs || {}).forEach(function (k) { e.setAttribute(k, attrs[k]); });
    return e;
  }
  function reducedMotion() {
    return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  }
  function setMark(node, cls) {                     // classList (not className) so it also works on SVG elements
    Array.prototype.slice.call(node.classList).forEach(function (c) { if (c.indexOf("m-") === 0) node.classList.remove(c); });
    if (cls) cls.split(" ").forEach(function (c) { if (c) node.classList.add("m-" + c); });
  }
  function labelled(kind, c) {
    var box = el("div", "pb-tr-comp pb-tr-" + kind + (c.inline ? " is-inline" : ""));
    if (c.label) box.appendChild(el("div", "pb-tr-label", c.label));
    return box;
  }

  // Pointer colours are assigned per name, in order of first appearance, so `l` keeps its colour all the way.
  function pointerPalette() {
    var seen = {};
    return function (name) {
      if (!(name in seen)) seen[name] = Object.keys(seen).length % 6;
      return seen[name];
    };
  }

  // ------------------------------------------------------------------ array
  function buildArray(c, host, colour) {
    var box = labelled("array", c);
    var scroller = el("div", "pb-tr-scroll");
    var track = el("div", "pb-tr-track");
    var cells = el("div", "pb-tr-cells");
    var ptrs = el("div", "pb-tr-ptrs");
    var unit = c.bars || 0;                         // bars: value × unit rem tall (e.g. heights, sort input)
    if (unit) {
      cells.classList.add("is-bars");
      track.classList.add("is-bars");               // narrower columns (and pointers follow via --tr-cw)
      cells.style.setProperty("--tr-bars-h", (Math.max.apply(null, c.values.concat([c.maxBar || 0])) * unit + 0.2) + "rem");
    }
    var cellEls = c.values.map(function (v, i) {
      var cell = el("div", "pb-tr-cell" + (unit ? " is-bar" : ""));
      if (unit) {
        var col = el("div", "pb-tr-barcol");
        col.appendChild(el("div", "pb-tr-water"));
        col.appendChild(el("div", "pb-tr-bar"));
        cell.appendChild(col);
      }
      cell.appendChild(el("span", "pb-tr-val", String(v)));
      if (c.indexes !== false) cell.appendChild(el("span", "pb-tr-idx", String(i)));
      cells.appendChild(cell);
      return cell;
    });
    function setBar(cell, v, water) {
      if (!unit) return;
      var col = cell.firstChild;
      col.lastChild.style.height = (Number(v) || 0) * unit + "rem";
      col.firstChild.style.height = (water || 0) * unit + "rem";
    }
    track.appendChild(cells);
    track.appendChild(ptrs);
    scroller.appendChild(track);
    box.appendChild(scroller);
    host.appendChild(box);
    var ptrEls = {};
    return function update(s) {
      var vals = s.values || c.values;
      cellEls.forEach(function (cell, i) {
        cell.querySelector(".pb-tr-val").textContent = String(vals[i]);
        setBar(cell, vals[i], s.water && s.water[i]);
      });
      cellEls.forEach(function (cell, i) {
        var m = (s.marks && s.marks[i]) || "";
        if (s.win && i >= s.win[0] && i <= s.win[1]) m = (m + " win").trim();
        setMark(cell, m);
      });
      var rank = {}, rows = 1;
      Object.keys(s.ptrs || {}).forEach(function (name) {
        var p = ptrEls[name];
        if (!p) {
          p = ptrEls[name] = el("div", "pb-tr-ptr", "▲ " + name);
          p.setAttribute("data-k", colour(name));
          ptrs.appendChild(p);
        }
        var idx = s.ptrs[name];
        if (idx === null || idx === undefined || idx < 0 || idx >= cellEls.length) { p.hidden = true; return; }
        p.hidden = false;
        var r = rank[idx] = (rank[idx] || 0) + 1;
        rows = Math.max(rows, r);
        p.style.setProperty("--i", idx);
        p.style.setProperty("--r", r - 1);
      });
      Object.keys(ptrEls).forEach(function (name) { if (!s.ptrs || !(name in s.ptrs)) ptrEls[name].hidden = true; });
      ptrs.style.setProperty("--rows", rows);
    };
  }

  // ------------------------------------------------------------------- grid
  function buildGrid(c, host) {
    var box = labelled("grid", c);
    var scroller = el("div", "pb-tr-scroll");
    var table = el("table", "pb-tr-table");
    var cellEls = [];
    if (c.colLabels) {
      var head = el("tr");
      head.appendChild(el("th", "pb-tr-corner", ""));
      c.colLabels.forEach(function (l) { head.appendChild(el("th", "", l)); });
      table.appendChild(head);
    }
    for (var r = 0; r < c.rows; r++) {
      var tr = el("tr");
      if (c.rowLabels) tr.appendChild(el("th", "", c.rowLabels[r]));
      cellEls.push([]);
      for (var k = 0; k < c.cols; k++) {
        var td = el("td", "pb-tr-gcell", c.values ? String(c.values[r][k]) : "");
        tr.appendChild(td);
        cellEls[r].push(td);
      }
      table.appendChild(tr);
    }
    scroller.appendChild(table);
    box.appendChild(scroller);
    host.appendChild(box);
    return function update(s) {
      if (s.values) s.values.forEach(function (row, r) {
        row.forEach(function (v, k) { cellEls[r][k].textContent = v === null ? "" : String(v); });
      });
      cellEls.forEach(function (row, r) {
        row.forEach(function (td, k) { setMark(td, (s.marks && s.marks[r + "," + k]) || ""); });
      });
    };
  }

  // ------------------------------------------------------------------- list
  var NW = 46, NH = 34, STEP = 82, X0 = 18, Y0 = 26;
  function buildList(c, host, colour) {
    var box = labelled("list", c);
    var scroller = el("div", "pb-tr-scroll");
    var n = c.nodes.length;
    var width = X0 * 2 + (n - 1) * STEP + NW + 40;
    var height = Y0 + NH + 56 + 3 * 18;
    var root = svg("svg", { viewBox: "0 0 " + width + " " + height, width: width, height: height, class: "pb-tr-svg" });
    var uid = "a" + Math.random().toString(36).slice(2, 8);
    var defs = svg("defs");
    var marker = svg("marker", { id: uid, viewBox: "0 0 10 10", refX: "9", refY: "5", markerWidth: "7", markerHeight: "7", orient: "auto-start-reverse" });
    marker.appendChild(svg("path", { d: "M0 0 L10 5 L0 10 z", class: "pb-tr-arrowhead" }));
    defs.appendChild(marker);
    root.appendChild(defs);
    var arrows = svg("g", { class: "pb-tr-arrows" });
    root.appendChild(arrows);
    var nodeEls = c.nodes.map(function (v, i) {
      var g = svg("g", { class: "pb-tr-node" });
      g.appendChild(svg("rect", { x: X0 + i * STEP, y: Y0, width: NW, height: NH, rx: 9 }));
      var t = svg("text", { x: X0 + i * STEP + NW / 2, y: Y0 + NH / 2 + 5, "text-anchor": "middle" });
      t.textContent = String(v);
      g.appendChild(t);
      root.appendChild(g);
      return g;
    });
    var ptrLayer = svg("g", { class: "pb-tr-ptrlayer" });
    root.appendChild(ptrLayer);
    scroller.appendChild(root);
    box.appendChild(scroller);
    host.appendChild(box);
    var ptrEls = {};

    function arrowPath(i, j) {
      var xi = X0 + i * STEP, xj = X0 + j * STEP;
      if (j === i + 1) return "M" + (xi + NW) + " " + (Y0 + 11) + " L" + (xj - 2) + " " + (Y0 + 11);
      if (j === i - 1) return "M" + xi + " " + (Y0 + NH - 9) + " L" + (xj + NW + 2) + " " + (Y0 + NH - 9);
      var below = j < i, cy = below ? Y0 + NH + 40 : Y0 - 22, y = below ? Y0 + NH : Y0;
      return "M" + (xi + NW / 2) + " " + y + " C" + (xi + NW / 2) + " " + cy + " " + (xj + NW / 2) + " " + cy + " " + (xj + NW / 2) + " " + (below ? y + 2 : y - 2);
    }

    return function update(s) {
      while (arrows.firstChild) arrows.removeChild(arrows.firstChild);
      (s.next || []).forEach(function (j, i) {
        if (j === null || j === undefined) return;
        arrows.appendChild(svg("path", { d: arrowPath(i, j), "marker-end": "url(#" + uid + ")", class: j < i ? "is-back" : "" }));
      });
      nodeEls.forEach(function (g, i) { setMark(g, (s.marks && s.marks[i]) || ""); });
      var rank = {};
      Object.keys(s.ptrs || {}).forEach(function (name) {
        var p = ptrEls[name];
        if (!p) {
          p = ptrEls[name] = svg("g", { class: "pb-tr-sptr", "data-k": colour(name) });
          var t = svg("text", { "text-anchor": "middle" });
          t.textContent = "▲ " + name;
          p.appendChild(t);
          ptrLayer.appendChild(p);
        }
        var idx = s.ptrs[name];
        if (idx === null || idx === undefined) { p.style.opacity = 0; return; }
        var r = rank[idx] = (rank[idx] || 0) + 1;
        p.style.opacity = 1;
        p.style.transform = "translate(" + (X0 + idx * STEP + NW / 2) + "px," + (Y0 + NH + 58 + (r - 1) * 18) + "px)";
      });
      Object.keys(ptrEls).forEach(function (name) { if (!s.ptrs || !(name in s.ptrs)) ptrEls[name].style.opacity = 0; });
    };
  }

  // ------------------------------------------------------------------ stack
  function buildStack(c, host) {
    var box = labelled("stack", c);
    var col = el("div", "pb-tr-stackcol");
    box.appendChild(col);
    host.appendChild(box);
    var prev = 0;
    return function update(s) {
      var items = s.items || [];
      col.textContent = "";
      if (!items.length) col.appendChild(el("div", "pb-tr-empty", "empty"));
      items.forEach(function (v, i) {
        var it = el("div", "pb-tr-sitem", String(v));
        setMark(it, (s.marks && s.marks[i]) || "");
        if (i >= prev) it.classList.add("is-new");
        if (i === items.length - 1) it.classList.add("is-top");
        col.appendChild(it);
      });
      prev = items.length;
    };
  }

  // -------------------------------------------------------------------- map
  function buildMap(c, host) {
    var box = labelled("map", c);
    var table = el("table", "pb-tr-map");
    box.appendChild(table);
    host.appendChild(box);
    return function update(s) {
      table.textContent = "";
      var entries = s.entries || [];
      if (!entries.length) {
        var tr0 = el("tr");
        tr0.appendChild(el("td", "pb-tr-empty", "{ }"));
        table.appendChild(tr0);
      }
      entries.forEach(function (kv) {
        var tr = el("tr");
        tr.appendChild(el("td", "pb-tr-key", String(kv[0])));
        tr.appendChild(el("td", "", "→ " + String(kv[1])));
        setMark(tr, (s.marks && s.marks[String(kv[0])]) || "");
        table.appendChild(tr);
      });
    };
  }

  // ------------------------------------------------------------------- vars
  function buildVars(c, host) {
    var box = labelled("vars", c);
    var row = el("div", "pb-tr-varrow");
    box.appendChild(row);
    host.appendChild(box);
    var last = {};
    return function update(s) {
      row.textContent = "";
      (s.items || []).forEach(function (kv) {
        var chip = el("span", "pb-tr-var");
        chip.appendChild(el("span", "pb-tr-vname", kv[0]));
        chip.appendChild(el("span", "pb-tr-vval", String(kv[1])));
        if (kv[0] in last && last[kv[0]] !== String(kv[1])) chip.classList.add("is-changed");
        row.appendChild(chip);
      });
      last = {};
      (s.items || []).forEach(function (kv) { last[kv[0]] = String(kv[1]); });
    };
  }

  // ------------------------------------------------------------------ queue (front on the left)
  function buildQueue(c, host) {
    var box = labelled("queue", c);
    var row = el("div", "pb-tr-queuerow");
    box.appendChild(row);
    host.appendChild(box);
    return function update(s) {
      var items = s.items || [];
      row.textContent = "";
      if (!items.length) row.appendChild(el("div", "pb-tr-empty", "empty"));
      items.forEach(function (v, i) {
        var it = el("div", "pb-tr-qitem", String(v));
        setMark(it, (s.marks && s.marks[i]) || "");
        if (i === 0) it.classList.add("is-front");
        row.appendChild(it);
      });
    };
  }

  // ------------------------------------------------------------------ graph / tree (SVG)
  // c.nodes: [{id, label, x, y}] in layout units; c.edges: [[u, v, weight?]]; c.directed.
  // state: marks {id: cls}, edges {"u-v": cls}, labels {id: text}, values {id: text}, hide [ids], ptrs {name: id}
  var GU = 62, GR = 19, GPAD = 34;
  function buildGraph(c, host, colour) {
    var box = labelled("graph", c);
    var scroller = el("div", "pb-tr-scroll");
    var maxX = 0, maxY = 0, pos = {};
    c.nodes.forEach(function (n) {
      pos[n.id] = { x: GPAD + n.x * GU, y: GPAD + n.y * GU };
      maxX = Math.max(maxX, n.x);
      maxY = Math.max(maxY, n.y);
    });
    var width = GPAD * 2 + maxX * GU + 60, height = GPAD * 2 + maxY * GU + 46;
    var root = svg("svg", { viewBox: "0 0 " + width + " " + height, width: width, height: height, class: "pb-tr-svg pb-tr-gsvg" });
    var uid = "g" + Math.random().toString(36).slice(2, 8);
    var defs = svg("defs");
    var marker = svg("marker", { id: uid, viewBox: "0 0 10 10", refX: "9", refY: "5", markerWidth: "7", markerHeight: "7", orient: "auto-start-reverse" });
    marker.appendChild(svg("path", { d: "M0 0 L10 5 L0 10 z", class: "pb-tr-arrowhead" }));
    defs.appendChild(marker);
    root.appendChild(defs);
    var edgeLayer = svg("g", { class: "pb-tr-edges" }), nodeLayer = svg("g"), ptrLayer = svg("g", { class: "pb-tr-ptrlayer" });
    root.appendChild(edgeLayer);
    root.appendChild(nodeLayer);
    root.appendChild(ptrLayer);
    var edgeEls = {};
    c.edges.forEach(function (e) {
      var a = pos[e[0]], b = pos[e[1]];
      var dx = b.x - a.x, dy = b.y - a.y, len = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / len, uy = dy / len;
      var g = svg("g", { class: "pb-tr-edge" });
      var line = svg("line", { x1: a.x + ux * GR, y1: a.y + uy * GR, x2: b.x - ux * (GR + 3), y2: b.y - uy * (GR + 3) });
      if (c.directed) line.setAttribute("marker-end", "url(#" + uid + ")");
      g.appendChild(line);
      if (e.length > 2 && e[2] !== null) {
        var mx = (a.x + b.x) / 2 - uy * 11, my = (a.y + b.y) / 2 + ux * 11;
        var w = svg("text", { x: mx, y: my + 4, "text-anchor": "middle", class: "pb-tr-weight" });
        w.textContent = String(e[2]);
        g.appendChild(w);
      }
      edgeLayer.appendChild(g);
      edgeEls[e[0] + "-" + e[1]] = g;
    });
    var nodeEls = {};
    c.nodes.forEach(function (n) {
      var p = pos[n.id];
      var g = svg("g", { class: "pb-tr-node pb-tr-gnode" });
      g.appendChild(svg("circle", { cx: p.x, cy: p.y, r: GR }));
      var t = svg("text", { x: p.x, y: p.y + 5, "text-anchor": "middle" });
      t.textContent = String(n.label);
      g.appendChild(t);
      var badge = svg("text", { x: p.x + GR + 5, y: p.y - GR + 6, class: "pb-tr-badge" });
      g.appendChild(badge);
      nodeLayer.appendChild(g);
      nodeEls[n.id] = { g: g, t: t, badge: badge, label: String(n.label) };
    });
    scroller.appendChild(root);
    box.appendChild(scroller);
    host.appendChild(box);
    var ptrEls = {};
    return function update(s) {
      var hidden = {};
      (s.hide || []).forEach(function (id) { hidden[id] = true; });
      Object.keys(nodeEls).forEach(function (id) {
        var n = nodeEls[id];
        setMark(n.g, (s.marks && s.marks[id]) || "");
        n.g.classList.toggle("is-gone", !!hidden[id]);
        n.t.textContent = s.values && id in s.values ? String(s.values[id]) : n.label;
        n.badge.textContent = s.labels && id in s.labels ? String(s.labels[id]) : "";
      });
      c.edges.forEach(function (e) {
        var key = e[0] + "-" + e[1], g = edgeEls[key];
        setMark(g, (s.edges && (s.edges[key] || (!c.directed && s.edges[e[1] + "-" + e[0]]))) || "");
        g.classList.toggle("is-gone", !!(hidden[e[0]] || hidden[e[1]]));
      });
      var rank = {};
      Object.keys(s.ptrs || {}).forEach(function (name) {
        var p = ptrEls[name];
        if (!p) {
          p = ptrEls[name] = svg("g", { class: "pb-tr-sptr", "data-k": colour(name) });
          var t = svg("text", { "text-anchor": "middle" });
          t.textContent = "▲ " + name;
          p.appendChild(t);
          ptrLayer.appendChild(p);
        }
        var id = s.ptrs[name];
        if (id === null || id === undefined || !(id in pos)) { p.style.opacity = 0; return; }
        var r = rank[id] = (rank[id] || 0) + 1;
        p.style.opacity = 1;
        p.style.transform = "translate(" + pos[id].x + "px," + (pos[id].y + GR + 15 + (r - 1) * 15) + "px)";
      });
      Object.keys(ptrEls).forEach(function (name) { if (!s.ptrs || !(name in s.ptrs)) ptrEls[name].style.opacity = 0; });
    };
  }

  var BUILD = { array: buildArray, grid: buildGrid, list: buildList, stack: buildStack, map: buildMap, vars: buildVars,
                queue: buildQueue, graph: buildGraph };

  // ------------------------------------------------------------------- init
  function init(root) {
    var dataEl = root.querySelector("script.pb-trace-data");
    if (!dataEl) return;
    var data = JSON.parse(dataEl.textContent);
    var colour = pointerPalette();

    var stage = el("div", "pb-tr-stage");
    var viz = el("div", "pb-tr-viz");
    var updates = data.layout.map(function (c) { return { id: c.id, fn: BUILD[c.type](c, viz, colour) }; });
    stage.appendChild(viz);

    var lines = [];
    if (data.code && data.code.length) {
      var code = el("pre", "pb-tr-code");
      data.code.forEach(function (line, k) {
        var ln = el("span", "pb-tr-line");
        ln.appendChild(el("span", "pb-tr-ln", String(k + 1)));
        ln.appendChild(document.createTextNode(line + "\n"));
        code.appendChild(ln);
        lines.push(ln);
      });
      stage.appendChild(code);
    }

    var caption = el("div", "pb-tr-caption");
    caption.setAttribute("aria-live", "polite");
    var bar = el("div", "pb-tr-controls");
    function btn(cls, label, icon) {
      var b = el("button", "pb-tr-btn " + cls, icon);
      b.type = "button";
      b.title = label;
      b.setAttribute("aria-label", label);
      bar.appendChild(b);
      return b;
    }
    var restart = btn("pb-tr-restart", "Restart", "↺");
    var prev = btn("pb-tr-prev", "Previous step", "‹");
    var play = btn("pb-tr-play", "Play", "▶");
    var next = btn("pb-tr-next", "Next step", "›");
    var counter = el("span", "pb-tr-counter");
    bar.appendChild(counter);
    var hint = el("span", "pb-tr-hint", "← → keys step");
    bar.appendChild(hint);

    root.appendChild(stage);
    root.appendChild(caption);
    root.appendChild(bar);
    root.classList.add("is-enhanced");
    root.tabIndex = -1;
    if (reducedMotion()) root.classList.add("is-reduced");

    var at = 0, timer = null;
    function show(i) {
      at = Math.max(0, Math.min(data.frames.length - 1, i));
      var f = data.frames[at];
      updates.forEach(function (u) { u.fn(f.state[u.id] || {}); });
      lines.forEach(function (ln, k) { ln.classList.toggle("is-active", k === f.line); });
      caption.innerHTML = '<span class="pb-tr-num">' + (at + 1) + "</span><span>" + f.caption + "</span>";
      counter.textContent = "Step " + (at + 1) + " / " + data.frames.length;
      prev.disabled = at === 0;
      next.disabled = at === data.frames.length - 1;
    }
    function stop() {
      clearInterval(timer);
      timer = null;
      play.textContent = "▶";
      play.title = "Play";
      play.setAttribute("aria-label", "Play");
    }
    function start() {
      if (at >= data.frames.length - 1) show(0);
      play.textContent = "❚❚";
      play.title = "Pause";
      play.setAttribute("aria-label", "Pause");
      timer = setInterval(function () {
        if (at >= data.frames.length - 1) return stop();
        show(at + 1);
      }, PLAY_MS);
    }
    restart.addEventListener("click", function () { stop(); show(0); });
    prev.addEventListener("click", function () { stop(); show(at - 1); });
    next.addEventListener("click", function () { stop(); show(at + 1); });
    play.addEventListener("click", function () { timer ? stop() : start(); });
    root.addEventListener("keydown", function (e) {
      if (e.key === "ArrowRight") { e.preventDefault(); stop(); show(at + 1); }
      if (e.key === "ArrowLeft") { e.preventDefault(); stop(); show(at - 1); }
    });
    // Material's instant navigation swaps the page without unloading: stop timers that outlive their page.
    var guard = setInterval(function () { if (!document.body.contains(root)) { stop(); clearInterval(guard); } }, 2000);
    show(0);
  }

  function initAll() {
    document.querySelectorAll("[data-pb-trace]:not(.is-enhanced)").forEach(init);
  }
  if (window.document$ && typeof window.document$.subscribe === "function") window.document$.subscribe(initAll);
  else if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initAll);
  else initAll();
})();
